describe('External Links Open in New Tab', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should open external links in a new tab with target="_blank"', () => {
    cy.get('a[href*="http"]').each(($link) => {
      cy.wrap($link).should('have.attr', 'target', '_blank');
    });
  });

  it('should open external links in a new tab and verify href is external', () => {
    cy.get('a').each(($link) => {
      const href = $link.attr('href');
      if (href && (href.startsWith('http://') || href.startsWith('https://'))) {
        cy.wrap($link).should('have.attr', 'target', '_blank');
        cy.wrap($link).should('have.attr', 'rel').and('include', 'noopener');
      }
    });
  });

  it('should not open internal links in a new tab', () => {
    cy.get('a[href^="/"]').each(($link) => {
      cy.wrap($link).should('not.have.attr', 'target', '_blank');
    });
  });

  it('should handle external links with various protocols correctly', () => {
    const externalLinks = [
      'https://example.com',
      'http://example.org',
      'https://subdomain.example.net'
    ];

    externalLinks.forEach((url) => {
      cy.get(`a[href="${url}"]`).should('have.attr', 'target', '_blank');
      cy.get(`a[href="${url}"]`).should('have.attr', 'rel').and('include', 'noopener');
    });
  });

  it('should verify external link opens without breaking the current page', () => {
    cy.get('a[target="_blank"]').first().then(($link) => {
      const href = $link.attr('href');
      cy.wrap($link).should('have.attr', 'target', '_blank');
      cy.wrap($link).should('have.attr', 'rel').and('include', 'noopener');
      cy.url().should('not.equal', href);
    });
  });

  it('should handle edge case of external links without rel attribute', () => {
    cy.get('a[href*="http"][target="_blank"]').each(($link) => {
      const rel = $link.attr('rel');
      if (rel) {
        cy.wrap($link).should('have.attr', 'rel').and('include', 'noopener');
      }
    });
  });

  it('should verify external links have proper accessibility attributes', () => {
    cy.get('a[target="_blank"]').each(($link) => {
      const href = $link.attr('href');
      if (href && (href.startsWith('http://') || href.startsWith('https://'))) {
        cy.wrap($link).should('have.attr', 'aria-label').or('have.text');
      }
    });
  });

  it('should handle mailto and tel links appropriately', () => {
    cy.get('a[href^="mailto:"]').each(($link) => {
      cy.wrap($link).should('not.have.attr', 'target', '_blank');
    });

    cy.get('a[href^="tel:"]').each(($link) => {
      cy.wrap($link).should('not.have.attr', 'target', '_blank');
    });
  });
});
